window.VO = [{"id":"n01","text":"You're the guard, and what you write in this register sends a man to jail.","at":0.24,"t0":0.12,"t1":5.575},{"id":"n02","text":"Flats are being robbed on this street, so ask this delivery man his name.","at":11.65,"t0":5.825,"t1":10.916},{"id":"a01","text":"Ravi, sir.","at":22.23,"t0":11.115,"t1":11.842},{"id":"n03","text":"Write it down, and ask which flat.","at":23.986,"t0":11.993,"t1":14.538},{"id":"b01","text":"Three zero two.","at":29.376,"t0":14.688,"t1":15.779},{"id":"n04","text":"Write that too, but anyone can say a flat number, so check his parcel.","at":31.958,"t0":15.979,"t1":21.07},{"id":"c01","text":"Here, sir.","at":42.44,"t0":21.22,"t1":21.947},{"id":"n05","text":"Does the label match your register?","at":44.294,"t0":22.147,"t1":24.329},{"id":"n06","text":"It doesn't. Good catch.","at":51.058,"t0":25.529,"t1":26.984},{"id":"d01","text":"Sorry, sir. I'll call the customer.","at":54.468,"t0":27.234,"t1":29.416},{"id":"n07","text":"So nobody got past you.","at":59.53,"t0":29.765,"t1":31.583},{"id":"n08","text":"Then who robbed flat three zero two?","at":63.568,"t0":31.784,"t1":34.329},{"id":"n09","text":"Police have four men in that jacket, but your register says one came, so point at him.","at":69.058,"t0":34.529,"t1":40.711},{"id":"n10","text":"He goes to jail, and the other three go home.","at":81.822,"t0":40.911,"t1":44.547},{"id":"n11","text":"Which one? You looked right at him.","at":89.494,"t0":44.747,"t1":47.292},{"id":"n12","text":"You're right. He was at your gate, and so were the other three.","at":98.786,"t0":49.393,"t1":54.12},{"id":"n13","text":"Every time you looked down, one walked in and the next stepped up, and you carried on.","at":109.74,"t0":54.87,"t1":61.052},{"id":"n14","text":"So three of them go home. Four, if you said none.","at":122.704,"t0":61.352,"t1":65.352},{"id":"n15","text":"Psychologists once swapped a man in a hard hat for another, and one woman who missed it said she'd just seen a construction worker.","at":131.504,"t0":65.752,"t1":74.479},{"id":"n16","text":"And these four aren't even delivery men. You just saw a jacket.","at":149.558,"t0":74.779,"t1":79.143},{"id":"n17","text":"Your register says Ravi.","at":159.186,"t0":79.593,"t1":81.048},{"id":"n18","text":"So which one was Ravi?","at":162.494,"t0":81.247,"t1":83.065}];
